contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logAddr) public {
        // Before initialization, setting the log succeeds
        c.SetLogFile(logAddr);
        bool reverted1;
        try c.SetLogFile(logAddr) { reverted1 = false; } catch { reverted1 = true; }
        // Before initialization, SetLogFile does not revert when called the second time (state unchanged between)
        assert(!reverted1);
        // Initialize
        c.Initialized();
        // Now SetLogFile must revert
        bool reverted2;
        try c.SetLogFile(logAddr) { reverted2 = false; } catch { reverted2 = true; }
        assert(reverted2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _log) public {
        // Before initialization, SetLogFile succeeds and stores _log.
        c.SetLogFile(_log);
        address before = address(c.Log());
        c.Initialized();
        bool reverted;
        try c.SetLogFile(_log) { reverted = false; } catch { reverted = true; }
        assert(reverted && address(c.Log()) == before);
    }
}

